const dictionaries: Record<Language, Translations> = {
  en,
  zh,
  "zh-TW": zhTW,
  ja,
  ko,
  es,
  fr,
  de,
  it,
  pt,
  ru,
  vi,
  th,
  id,
  ar,
}

interface I18nContextType {
  language: Language
  setLanguage: (lang: Language) => void
  t: (key: string, params?: Record<string, string | number>) => string
}

const I18nContext = createContext<I18nContextType>({
  language: "en",
  setLanguage: () => {},
  t: (key: string) => key,
})

function detectBrowserLanguage(): Language {
  if (typeof navigator === "undefined") return "en"
  const raw = navigator.language.toLowerCase()
  if (raw.includes("zh-tw") || raw.includes("zh-hk") || raw.includes("zh-mo") || raw.includes("hant")) {
    return "zh-TW"
  }
  if (raw.startsWith("zh")) return "zh"
  if (raw.startsWith("ja")) return "ja"
  if (raw.startsWith("ko")) return "ko"
  if (raw.startsWith("es")) return "es"
  if (raw.startsWith("fr")) return "fr"
  if (raw.startsWith("de")) return "de"
  if (raw.startsWith("it")) return "it"
  if (raw.startsWith("pt")) return "pt"
  if (raw.startsWith("ru")) return "ru"
  if (raw.startsWith("vi")) return "vi"
  if (raw.startsWith("th")) return "th"
  if (raw.startsWith("id") || raw.startsWith("ms")) return "id"
  if (raw.startsWith("ar")) return "ar"
  return "en"
}

function getInitialLanguage(): Language {
  if (typeof window === "undefined") {
    return "en"
  }
  try {
    const supported: Language[] = [
      "en", "zh", "zh-TW", "ja", "ko",
      "es", "fr", "de", "it", "pt",
      "ru", "vi", "th", "id", "ar"
    ]
    const saved = localStorage.getItem("closedui_lang") as Language | null
    if (saved && supported.includes(saved)) {
      return saved
    }
    const detected = detectBrowserLanguage()
    if (supported.includes(detected)) {
      return detected
    }
  } catch {}
  return "en"
}

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguageState] = useState<Language>("en")
  const [isHydrated, setIsHydrated] = useState(false)

  useEffect(() => {
    setLanguageState(getInitialLanguage())
    setIsHydrated(true)
  }, [])

  const setLanguage = (lang: Language) => {
    setLanguageState(lang)
    localStorage.setItem("closedui_lang", lang)
    if (typeof document !== "undefined") {
      document.documentElement.dir = lang === "ar" ? "rtl" : "ltr"
    }
  }

  const t = (key: string, params?: Record<string, string | number>): string => {
    let str = dictionaries[language]?.[key] || dictionaries.en?.[key] || key
    if (params) {
      for (const [k, v] of Object.entries(params)) {
        str = str.split(`{{${k}}}`).join(String(v))
      }
    }
    return str
  }

  return (
    <I18nContext.Provider value={{ language, setLanguage, t }}>
      <div style={{ visibility: isHydrated ? 'visible' : 'hidden', display: 'contents' }}>
        {children}
      </div>
    </I18nContext.Provider>
  )
}

export function useI18n() {
  return useContext(I18nContext)
}
